import assert from 'node:assert';
import { debounce } from './solution.ts';

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

async function main() {
  let calls = 0;
  const d = debounce(() => { calls++; }, 30);
  d(); d(); d();
  await sleep(60);
  assert.strictEqual(calls, 1, 'should collapse rapid calls into one');

  const d2 = debounce(() => { calls++; }, 30);
  d2();
  d2.cancel();
  await sleep(60);
  assert.strictEqual(calls, 1, 'cancel should abort pending invocation');

  console.log('OK');
}
main().catch((err) => { console.error(err); process.exit(1); });

tasks.mockAnswer:
export interface Debounced<A extends unknown[]> {
  (...args: A): void;
  cancel(): void;
}

export function debounce<T extends (...args: any[]) => void>(fn: T, ms: number): Debounced<Parameters<T>> {
  let timer: ReturnType<typeof setTimeout> | undefined;
  const wrapper = ((...args: Parameters<T>) => {
    if (timer !== undefined) clearTimeout(timer);
    timer = setTimeout(() => {
      timer = undefined;
      fn(...args);
    }, ms);
  }) as Debounced<Parameters<T>>;
  wrapper.cancel = () => {
    if (timer !== undefined) {
      clearTimeout(timer);
      timer = undefined;
    }
  };
  return wrapper;
}

