export function parsePorts(spec: string): number[] {
  const out: number[] = [];
  for (const raw of spec.split(',')) {
    const s = raw.trim();
    if (s === '') continue;
    const n = Number(s);
    if (!/^-?\d+$/.test(s) || !Number.isInteger(n) || n < 1 || n > 65535) {
      throw new Error(`invalid port: ${raw}`);
    }
    out.push(n);
  }
  return out;
}

